/// <summary>
/// Service class for sales order finalization automate.
/// </summary>
class METSalesOrderFinalizationAutomateService  extends METSysOperationService
{
    FromDate        fromDate;
    ToDate          toDate;
    List            warehouseList;
    private guid topPickingProcessId;

}

Method.Source:
/// <summary>
/// Returns task service class name.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METSalesOrderFinalizationAutomateTaskService);
}

/// <summary>
/// Returns task service class method.
/// </summary>
/// <returns>Task service class method</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METSalesOrderFinalizationAutomateTaskService, process);
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void process(METSalesOrderFinalizationAutomateContract _contract)
{
    METProcMetrics          procMetrics;
    METOrderTransactionType orderTransactionType = _contract.parmOrderTransactionType();

    switch (orderTransactionType)
    {
        case METOrderTransactionType::SalesOrder:
            procMetrics = METProcMetrics::construct(METBatchLogOperation::SalesFinalizationAutomation);
            break;

        case METOrderTransactionType::TransferOrder:
            procMetrics = METProcMetrics::construct(METBatchLogOperation::TransferFinalizationAutomation);
            break;

        default:
            procMetrics = METProcMetricsDummy::construct();
    }

    using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
    {
        this.processInternal(_contract);
        procMetrics.endTrace();
    }
}

/// <summary>Initialise global variables</summary>
public void initialise()
{
    super();

    METSalesOrderFinalizationAutomateContract contract = dataContract as METSalesOrderFinalizationAutomateContract;
    this.executeOperation(contract);

}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    METSalesOrderFinalizationAutomateContract contract = _taskDataContract as METSalesOrderFinalizationAutomateContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METSalesOrderFinalizationAutomateContract();
}

/// <summary>
/// Method to initiate business process
/// </summary>
/// <param name = "_contract">Contract class reference</param>
public void executeOperation(METSalesOrderFinalizationAutomateContract _contract)
{
    RecordInsertList    shipmentConfirmationRecordList;
    METSalesOrderShipmentConfirmationQueue  postQueue;
    #OCCRetryCount

    METSalesOrderShipmentConfirmationQueue::cleanUpPostSalesOrderCreationProcessingQueue();
    shipmentConfirmationRecordList = new RecordInsertList(tableNum(METSalesOrderShipmentConfirmationQueue));
    topPickingProcessId = newGuid();

    QueryRun                        queryRun;
    Query                           query = new Query();
    QueryBuildDataSource            qbdsLoadHeader = query.addDataSource(tableNum(METSalesOrderShipmentLoadHeader));
    QueryBuildRange                 warehouseRange;
    METSalesOrderShipmentLoadHeader metSalesOrderShipmentLoadHeader;
    METSalesOrderShipmentLoadLines  metSalesOrderShipmentLoadLines;
    METContainerTypeTable           mETContainerTypeTable;
    ListIterator                    literator;
    Map                             filteredMap = new Map(Types::Int64, Types::String);
    METProcMetrics                  procMetrics = METProcMetricsScope::current();
    boolean                         shipmentLevelExecution = false;
    WHSParameters                   whsParameters = WHSParameters::find();

    warehouseList = _contract.parmWarehouseList();
    fromDate = _contract.parmFromDate();
    toDate = _contract.parmToDate();

    qbdsLoadHeader.addRange(fieldNum(METSalesOrderShipmentLoadHeader, ConfirmedShipDate)).value(queryRange(fromDate, toDate));
    qbdsLoadHeader.addRange(fieldNum(METSalesOrderShipmentLoadHeader, ShipmentStatus)).value(queryValue(MetShipmentStatus::Open));
    qbdsLoadHeader.addRange(fieldNum(METSalesOrderShipmentLoadHeader, ShipmentStatus)).value(queryValue(MetShipmentStatus::Loaded));
    qbdsLoadHeader.addRange(fieldNum(METSalesOrderShipmentLoadHeader, TransactionType)).value(queryValue(_contract.parmOrderTransactionType()));

    literator = new ListIterator(warehouseList);

    while (literator.more())
    {
        warehouseRange = qbdsLoadHeader.addRange(fieldNum(METSalesOrderShipmentLoadHeader, Warehouse));
        warehouseRange.value(queryValue(literator.value()));
        literator.next();
    }

    queryRun = new QueryRun(query);

    if (procMetrics)
    {
        procMetrics.setTotalCountFromQuery(queryRun);
        procMetrics.beginTrace('Process started');
        //Or use procMetrics start trace method: pass count & description to set and start the log in one call
    }

    METCustTable metCustTable;
    while (queryrun.next())
    {
        metSalesOrderShipmentLoadHeader = queryRun.get(tableNum(METSalesOrderShipmentLoadHeader));

        metCustTable = METCustTable::find(metSalesOrderShipmentLoadHeader.CustAccount);

        if (metSalesOrderShipmentLoadHeader.displayLoadPickComplete() == NoYes::Yes && metSalesOrderShipmentLoadHeader.isValidShipmentToShipped())
        {
            try
            {
                ttsbegin;

                if (!shipmentLevelExecution)
                {
                    shipmentLevelExecution = true;
                }

                if (metCustTable.FinalizationDocument != METFinalizationDocument::None)
                {
                    Info("@MET:ShipmentThreads");

                    while select ShipmentId, OrderNum from metSalesOrderShipmentLoadLines
                    group by ShipmentId, OrderNum
                        where metSalesOrderShipmentLoadLines.ShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId
                    {
                        postQueue.clear();
                        postQueue.ProcessId = this.topPickingProcessId;
                        postQueue.ShipmentId = metSalesOrderShipmentLoadLines.ShipmentId;
                        postQueue.SalesId = metSalesOrderShipmentLoadLines.OrderNum;
                        postQueue.ShipmentLevelExecute = shipmentLevelExecution;
                        shipmentConfirmationRecordList.add(postQueue);

                        shipmentLevelExecution = false;
                    }
                }
                else
                {
                    postQueue.clear();
                    postQueue.ProcessId = this.topPickingProcessId;
                    postQueue.ShipmentId = metSalesOrderShipmentLoadHeader.ShipmentId;
                    postQueue.ShipmentLevelExecute = shipmentLevelExecution;

                    shipmentConfirmationRecordList.add(postQueue);
                }

                METSalesOrderShipmentLoadHeader::updateDocStatusInHeader(MetShipmentStatus::Loaded, DocumentStatus::None, metSalesOrderShipmentLoadHeader.ShipmentId);

                ttscommit;

                if (procMetrics)
                {
                    procMetrics.incProcessedCount();
                }
            }
            catch (Exception::Deadlock)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::Deadlock;
                }
                else
                {
                    retry;
                }
            }
            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        throw Exception::UpdateConflictNotRecovered;
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    throw Exception::UpdateConflict;
                }
            }
            catch (Exception::Error)
            {
                exceptionTextFallThrough();
            }
        }
    }

    shipmentConfirmationRecordList.insertDatabase();
}
